"use client";

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { IconMorph, type IconMorphPaths } from "../icon-morph/icon-morph";
import { motionTokens } from "../lib/motion-tokens";
import { MorphingText } from "../morphing-text/morphing-text";
import "../foundation.css";

export type ButtonVariant = "filled" | "bordered" | "text";
export type ButtonTone = "primary" | "secondary" | "success" | "warning" | "danger";
export type ButtonSize = "small" | "medium" | "large";

const baseClass = "inline-flex w-fit items-center justify-center gap-2 whitespace-nowrap rounded-[18px] border font-[inherit] font-[650] leading-none no-underline transition-[opacity,background-color,border-color,color,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] aria-disabled:cursor-not-allowed aria-disabled:opacity-[0.48] active:not-disabled:translate-y-px";

const sizeClasses: Record<ButtonSize, string> = {
  small: "min-h-10 px-4 text-xs",
  medium: "min-h-[46px] px-5 text-[13px]",
  large: "min-h-[52px] px-6 text-sm",
};

const appearanceClasses: Record<ButtonVariant, Record<ButtonTone, string>> = {
  filled: {
    primary: "border-transparent bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary-hover)]",
    secondary: "border-transparent bg-[var(--surface-muted)] text-[var(--text)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))]",
    success: "border-transparent bg-[var(--surface-muted)] text-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-transparent bg-[var(--surface-muted)] text-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-transparent bg-[var(--surface-muted)] text-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  bordered: {
    primary: "border-[color-mix(in_srgb,var(--text)_75%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text)] hover:border-[var(--text)] hover:bg-[color-mix(in_srgb,var(--primary)_25%,transparent)]",
    secondary: "border-[color-mix(in_srgb,var(--text-secondary)_72%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text-secondary)] hover:border-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--success-surface-foreground)] hover:border-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--warning-surface-foreground)] hover:border-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--danger-surface-foreground)] hover:border-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  text: {
    primary: "border-transparent bg-transparent text-[var(--text)] hover:bg-[var(--surface-muted)]",
    secondary: "border-transparent bg-transparent text-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-transparent bg-transparent text-[var(--success-surface-foreground)] hover:bg-[var(--surface-muted)]",
    warning: "border-transparent bg-transparent text-[var(--warning-surface-foreground)] hover:bg-[var(--surface-muted)]",
    danger: "border-transparent bg-transparent text-[var(--danger-surface-foreground)] hover:bg-[var(--surface-muted)]",
  },
};

function classes(variant: ButtonVariant, tone: ButtonTone, size: ButtonSize, className?: string) {
  return [baseClass, sizeClasses[size], appearanceClasses[variant][tone], className]
    .filter(Boolean)
    .join(" ");
}

interface ButtonStyleProps {
  variant?: ButtonVariant;
  tone?: ButtonTone;
  size?: ButtonSize;
}

type OneOrMany<Value> = Value | readonly Value[];

export interface ButtonProps
  extends Omit<ComponentPropsWithoutRef<"button">, "children"> {
  variant?: ButtonVariant;
  tone?: OneOrMany<ButtonTone>;
  size?: ButtonSize;
  children?: ReactNode;
  label?: OneOrMany<string>;
  icon?: OneOrMany<ReactNode>;
  iconPosition?: "start" | "end";
  loading?: OneOrMany<boolean>;
  state?: number;
  iconPaths?: IconMorphPaths;
}

function atState<Value>(value: OneOrMany<Value> | undefined, state: number) {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) return value as Value;
  return value[Math.min(state, value.length - 1)];
}

function ButtonIcon({ icons, state, paths, spinning }: {
  icons: OneOrMany<ReactNode>;
  state: number;
  paths?: IconMorphPaths;
  spinning?: boolean;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const values = Array.isArray(icons) ? icons : [icons];
  const current = values[Math.min(state, values.length - 1)];

  if (paths && values.length === 2) {
    return <IconMorph state={state > 0} from={values[0]} to={values[1]} paths={paths} size={18} />;
  }

  return (
    <span className="relative inline-grid size-[18px] place-items-center">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          className="absolute inset-0 grid origin-center place-items-center"
          key={state}
          initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
        >
          <motion.span
            className="grid place-items-center [&>svg]:size-[18px]"
            animate={{ rotate: spinning && !reduceMotion ? 360 : 0 }}
            transition={spinning && !reduceMotion
              ? { duration: 0.8, ease: "linear", repeat: Infinity }
              : { duration: 0 }}
          >
            {current}
          </motion.span>
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button({
  variant = "filled",
  tone = "primary",
  size = "medium",
  label,
  icon,
  iconPosition = "start",
  loading = false,
  state = 0,
  iconPaths,
  className,
  children,
  type = "button",
  ...props
}, ref) {
  const activeState = Math.max(0, Math.floor(state));
  const activeTone = atState(tone, activeState) ?? "primary";
  const isLoading = atState(loading, activeState) ?? false;
  const activeIcon = icon
    ? <ButtonIcon icons={icon} state={activeState} paths={iconPaths} spinning={isLoading} />
    : undefined;
  const content = label === undefined
    ? children
    : <MorphingText value={atState(label, activeState) ?? ""} />;
  const iconOnly = activeIcon !== undefined && content == null;

  return (
    <button
      ref={ref}
      {...props}
      type={type}
      aria-busy={isLoading || undefined}
      className={classes(variant, activeTone, size, [
        iconOnly && { small: "w-10 px-0", medium: "w-[46px] px-0", large: "w-[52px] px-0" }[size],
        className,
      ].filter(Boolean).join(" "))}
    >
      {activeIcon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
      {content}
      {activeIcon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
    </button>
  );
});

export interface ButtonLinkProps extends ComponentPropsWithoutRef<"a">, ButtonStyleProps {
  icon?: ReactNode;
  iconPosition?: "start" | "end";
}

export function ButtonLink({
  variant = "filled",
  tone = "primary",
  size = "medium",
  icon,
  iconPosition = "start",
  className,
  children,
  ...props
}: ButtonLinkProps) {
  return (
    <a {...props} className={classes(variant, tone, size, className)}>
      {icon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
      {children}
      {icon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
    </a>
  );
}

"use client";

import {
  forwardRef,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ComponentPropsWithoutRef,
  type MouseEventHandler,
  type ReactNode,
} from "react";
import { Eye, EyeOff, X } from "lucide-react";
import { Button, type ButtonSize } from "../button/button";
import "../foundation.css";

export type InputVariant = "filled" | "bordered";
export type InputType = "text" | "email" | "password" | "search" | "tel" | "url";
export type InputSize = ButtonSize;

interface CharacterItem {
  id: number;
  value: string;
  isNew: boolean;
  delay: number;
}

export interface InputProps
  extends Omit<ComponentPropsWithoutRef<"input">, "prefix" | "size" | "type" | "value" | "defaultValue"> {
  label?: string;
  hint?: string;
  error?: ReactNode;
  placeholder?: string;
  prefixIcon?: ReactNode;
  suffixIcon?: ReactNode;
  suffixControl?: ReactNode;
  variant?: InputVariant;
  size?: InputSize;
  dense?: boolean;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  clearLabel?: string;
  maskCharacter?: string;
  animationDuration?: number;
  valueFeedbackKey?: number;
  valueDisplay?: ReactNode;
  /** Allows valueDisplay to contain interactive controls such as removable chips. */
  valueDisplayInteractive?: boolean;
  /** Handles clicks inside an interactive value display. */
  onValueDisplayClick?: MouseEventHandler<HTMLDivElement>;
  clearable?: boolean;
  externalTrailing?: ReactNode;
  externalTrailingClassName?: string;
  type?: InputType;
  showPasswordToggle?: boolean;
  showPasswordLabel?: string;
  hidePasswordLabel?: string;
  expanded?: boolean;
  expandedContent?: ReactNode;
}

export const Input = forwardRef<HTMLInputElement, InputProps>(function Input({
  id,
  label,
  hint,
  error,
  placeholder,
  prefixIcon,
  suffixIcon,
  suffixControl,
  variant = "filled",
  size = "medium",
  dense = false,
  value,
  defaultValue = "",
  disabled,
  required,
  className,
  style,
  onChange,
  onScroll,
  onValueChange,
  clearLabel = "Clear input",
  maskCharacter = "•",
  animationDuration,
  valueFeedbackKey = 0,
  valueDisplay,
  valueDisplayInteractive = false,
  onValueDisplayClick,
  clearable = true,
  externalTrailing,
  externalTrailingClassName,
  type = "text",
  showPasswordToggle = false,
  showPasswordLabel = "Show password",
  hidePasswordLabel = "Hide password",
  expanded = false,
  expandedContent,
  "aria-describedby": ariaDescribedBy,
  ...props
}, forwardedRef) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const hintId = `${inputId}-hint`;
  const errorId = `${inputId}-error`;
  const inputRef = useRef<HTMLInputElement>(null);
  const overlayRef = useRef<HTMLDivElement>(null);
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [passwordVisible, setPasswordVisible] = useState(false);
  const currentValue = value ?? internalValue;
  const [characterState, setCharacterState] = useState<{
    value: string;
    items: CharacterItem[];
    nextId: number;
  }>(() => ({
    value: currentValue,
    items: Array.from(currentValue).map((character, index) => ({
      id: index,
      value: character,
      isNew: false,
      delay: 0,
    })),
    nextId: currentValue.length,
  }));
  const describedBy = [ariaDescribedBy, error ? errorId : hint ? hintId : undefined]
    .filter(Boolean)
    .join(" ") || undefined;
  const hasValue = currentValue.length > 0;
  const controlSize = dense ? "small" : size;
  const controlHeightClass = {
    small: "min-h-10",
    medium: "min-h-[46px]",
    large: "min-h-[52px]",
  }[controlSize];
  const contentHeightClass = {
    small: "min-h-[38px]",
    medium: "min-h-[44px]",
    large: "min-h-[50px]",
  }[controlSize];
  const appearanceClass = error
    ? "border-[var(--danger-surface-foreground)] bg-[color-mix(in_srgb,var(--danger-surface)_36%,var(--surface))] focus-within:border-[var(--danger-surface-foreground)]"
    : variant === "filled"
      ? "border-transparent bg-[var(--surface-muted)] focus-within:border-[var(--focus)]"
      : "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_58%,var(--surface))] focus-within:border-[var(--focus)]";
  const isPassword = type === "password";
  const resolvedType = isPassword && passwordVisible ? "text" : type;

  if (characterState.value !== currentValue) {
    const previousItems = characterState.items;
    const previousCharacters = previousItems.map((item) => item.value);
    const nextCharacters = Array.from(currentValue);
    const sequenceLengths = Array.from(
      { length: previousCharacters.length + 1 },
      () => Array<number>(nextCharacters.length + 1).fill(0),
    );

    for (let previousIndex = previousCharacters.length - 1; previousIndex >= 0; previousIndex -= 1) {
      for (let nextIndex = nextCharacters.length - 1; nextIndex >= 0; nextIndex -= 1) {
        sequenceLengths[previousIndex][nextIndex] = previousCharacters[previousIndex] === nextCharacters[nextIndex]
          ? (sequenceLengths[previousIndex + 1][nextIndex + 1] ?? 0) + 1
          : Math.max(
              sequenceLengths[previousIndex + 1][nextIndex] ?? 0,
              sequenceLengths[previousIndex][nextIndex + 1] ?? 0,
            );
      }
    }

    const items: CharacterItem[] = [];
    let nextId = characterState.nextId;
    let previousIndex = 0;
    let nextIndex = 0;
    let insertionIndex = 0;

    while (nextIndex < nextCharacters.length) {
      if (
        previousIndex < previousCharacters.length &&
        previousCharacters[previousIndex] === nextCharacters[nextIndex]
      ) {
        items.push({ ...previousItems[previousIndex], isNew: false, delay: 0 });
        previousIndex += 1;
        nextIndex += 1;
      } else if (
        previousIndex < previousCharacters.length &&
        (sequenceLengths[previousIndex + 1][nextIndex] ?? 0) >=
          (sequenceLengths[previousIndex][nextIndex + 1] ?? 0)
      ) {
        previousIndex += 1;
      } else {
        items.push({
          id: nextId,
          value: nextCharacters[nextIndex],
          isNew: true,
          delay: insertionIndex * 25,
        });
        nextId += 1;
        nextIndex += 1;
        insertionIndex += 1;
      }
    }

    setCharacterState({ value: currentValue, items, nextId });
  }

  useImperativeHandle(forwardedRef, () => inputRef.current as HTMLInputElement);

  const updateValue = (nextValue: string) => {
    if (value === undefined) setInternalValue(nextValue);
    onValueChange?.(nextValue);
  };

  const clear = () => {
    updateValue("");
    inputRef.current?.focus();
  };

  const syncVisualScroll = () => {
    if (overlayRef.current && inputRef.current) {
      overlayRef.current.scrollLeft = inputRef.current.scrollLeft;
    }
  };

  useLayoutEffect(() => {
    syncVisualScroll();
  }, [currentValue]);

  const settleCharacter = (characterId: number) => {
    setCharacterState((currentState) => {
      const item = currentState.items.find((character) => character.id === characterId);
      if (!item?.isNew) return currentState;

      return {
        ...currentState,
        items: currentState.items.map((character) =>
          character.id === characterId
            ? { ...character, isNew: false, delay: 0 }
            : character,
        ),
      };
    });
  };

  const displayCharacter = (character: string) =>
    isPassword && !passwordVisible ? maskCharacter : character === " " ? "\u00a0" : character;
  const hasAnimatingCharacters = characterState.items.some((item) => item.isNew);

  return (
    <div className={["relative grid w-full gap-2", expanded && "z-[120]", className].filter(Boolean).join(" ")}>
      {label ? <label className="text-[13px] leading-[1.4] font-[620] text-[var(--text)]" htmlFor={inputId}>{label}{required ? <span aria-hidden="true"> *</span> : null}</label> : null}
      <div className={[
        "relative min-w-0",
        expandedContent && controlHeightClass,
        externalTrailing && "grid min-w-0 grid-cols-[minmax(0,1fr)_var(--input-external-width,auto)] items-end gap-[var(--input-external-gap,4px)] transition-[grid-template-columns,gap] duration-[var(--duration-fast)] ease-[var(--ease-standard)]",
      ].filter(Boolean).join(" ")}>
        <div
          className={[
            "relative z-0 flex flex-col items-start overflow-hidden rounded-[18px] border text-[var(--text)] transition-[background-color,border-color,opacity] duration-[var(--duration-fast)] ease-[var(--ease-standard)] motion-reduce:duration-[0.01ms]",
            expandedContent && "absolute inset-x-0 top-0 w-full",
            controlHeightClass,
            appearanceClass,
            disabled && "cursor-not-allowed opacity-[0.52]",
            expanded && "z-[120] !border-transparent focus-within:!border-transparent",
          ].filter(Boolean).join(" ")}
          style={animationDuration
            ? ({ "--input-character-duration": `${animationDuration}ms` } as CSSProperties)
            : undefined}
        >
        <div className={[
          "grid w-full min-w-0 grid-cols-[auto_minmax(0,1fr)_auto] [grid-template-areas:'prefix_input_trailing'] items-center gap-2 px-3.5",
          contentHeightClass,
        ].filter(Boolean).join(" ")}>
          {prefixIcon ? <span className="[grid-area:prefix] grid shrink-0 place-items-center text-[var(--text-secondary)] [&>svg]:size-[18px]" aria-hidden="true">{prefixIcon}</span> : null}
          <div className={[
            "relative [grid-area:input] flex min-w-0 flex-1 items-center overflow-hidden",
            contentHeightClass,
          ].filter(Boolean).join(" ")}>
          <div
            ref={overlayRef}
            className={[
              "absolute inset-0 flex items-center overflow-hidden whitespace-nowrap text-[14px] leading-[1.5] tracking-[-0.01em] text-[var(--text)] [font-feature-settings:'kern'_0,'liga'_0,'clig'_0] [font-kerning:none] [font-variant-ligatures:none] select-none",
              valueDisplayInteractive ? "z-[2] pointer-events-auto" : "pointer-events-none",
              valueFeedbackKey > 0 && "animate-[sya-input-value-error-feedback_200ms_cubic-bezier(0.23,1,0.32,1)] motion-reduce:animate-[sya-input-value-error-feedback-reduced_160ms_ease-out]",
            ].filter(Boolean).join(" ")}
            key={valueFeedbackKey}
            aria-hidden={valueDisplayInteractive ? undefined : true}
            onClick={valueDisplayInteractive ? onValueDisplayClick : undefined}
          >
            <span data-input-value>
              {valueDisplay ?? (hasAnimatingCharacters
                ? characterState.items.map((item) => (
                    <span
                      className={item.isNew ? "inline-block animate-[sya-input-character-reveal_var(--input-character-duration,600ms)_cubic-bezier(0.16,1,0.3,1)_both] will-change-[transform,opacity] motion-reduce:inline motion-reduce:animate-none motion-reduce:transform-none motion-reduce:will-change-auto" : undefined}
                      key={item.id}
                      onAnimationEnd={() => settleCharacter(item.id)}
                      style={{ animationDelay: item.delay ? `${item.delay}ms` : undefined }}
                    >
                      {displayCharacter(item.value)}
                    </span>
                  ))
                : characterState.items.map((item) => displayCharacter(item.value)).join(""))}
            </span>
          </div>
          <input
            {...props}
            ref={inputRef}
            id={inputId}
            className={[
              "relative z-[1] h-full [min-height:inherit] w-full min-w-0 appearance-none border-0 bg-transparent p-0 text-[14px] leading-[1.5] tracking-[-0.01em] text-[var(--text)] caret-[var(--focus)] outline-none placeholder:text-[var(--text-secondary)] placeholder:opacity-100 [font-feature-settings:'kern'_0,'liga'_0,'clig'_0] [font-kerning:none] [font-variant-ligatures:none] disabled:cursor-not-allowed [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden",
              hasValue && "!text-transparent ![-webkit-text-fill-color:transparent] ![text-shadow:none]",
              isPassword && showPasswordToggle && "[&::-webkit-contacts-auto-fill-button]:pointer-events-none [&::-webkit-contacts-auto-fill-button]:invisible [&::-webkit-contacts-auto-fill-button]:absolute [&::-webkit-contacts-auto-fill-button]:right-0 [&::-webkit-credentials-auto-fill-button]:pointer-events-none [&::-webkit-credentials-auto-fill-button]:invisible [&::-webkit-credentials-auto-fill-button]:absolute [&::-webkit-credentials-auto-fill-button]:right-0",
            ].filter(Boolean).join(" ")}
            style={hasValue ? {
              ...style,
              color: "transparent",
              WebkitTextFillColor: "transparent",
            } : style}
            type={resolvedType}
            value={currentValue}
            placeholder={placeholder}
            disabled={disabled}
            required={required}
            aria-placeholder={placeholder}
            aria-invalid={Boolean(error) || undefined}
            aria-describedby={describedBy}
            onChange={(event) => {
              updateValue(event.currentTarget.value);
              onChange?.(event);
              requestAnimationFrame(syncVisualScroll);
            }}
            onScroll={(event) => {
              syncVisualScroll();
              onScroll?.(event);
            }}
            onKeyDown={(event) => {
              props.onKeyDown?.(event);
              requestAnimationFrame(syncVisualScroll);
            }}
            onKeyUp={(event) => {
              props.onKeyUp?.(event);
              requestAnimationFrame(syncVisualScroll);
            }}
            onClick={(event) => {
              props.onClick?.(event);
              requestAnimationFrame(syncVisualScroll);
            }}
          />
          </div>
          <span className="[grid-area:trailing] inline-flex min-w-0 items-center gap-2">
            {suffixIcon ? <span className="grid shrink-0 place-items-center text-[var(--text-secondary)] [&>svg]:size-[18px]" aria-hidden="true">{suffixIcon}</span> : null}
            {suffixControl ? <span className="inline-flex shrink-0 items-center">{suffixControl}</span> : null}
            {isPassword && showPasswordToggle && !disabled ? (
            <Button
              className="w-[30px] min-h-[30px] shrink-0 basis-[30px] p-0 [&_svg]:size-4"
              variant="text"
              tone="secondary"
              size="small"
              icon={passwordVisible ? <EyeOff /> : <Eye />}
              aria-label={passwordVisible ? hidePasswordLabel : showPasswordLabel}
              aria-pressed={passwordVisible}
              onClick={() => {
                setPasswordVisible((visible) => !visible);
                inputRef.current?.focus();
              }}
            />
            ) : null}
            {clearable && hasValue && !disabled ? (
            <Button
              className="w-[30px] min-h-[30px] shrink-0 basis-[30px] p-0 [&_svg]:size-4"
              variant="text"
              tone="secondary"
              size="small"
              icon={<X />}
              aria-label={clearLabel}
              onClick={clear}
            />
            ) : null}
          </span>
        </div>
        {expandedContent ? (
          <div className={["w-full min-h-0 shrink-0 basis-0 overflow-hidden transition-[flex-basis] duration-[480ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:duration-[0.01ms]", expanded && "basis-[var(--input-expanded-height,300px)]"].filter(Boolean).join(" ")} aria-hidden={!expanded}>
            <div className="min-h-0">{expandedContent}</div>
          </div>
        ) : null}
        </div>
        {externalTrailing ? <div className={[
          "inline-flex min-w-0 items-center gap-1 overflow-hidden",
          controlSize === "small" && "h-10 min-h-10",
          controlSize === "medium" && "h-[46px] min-h-[46px]",
          controlSize === "large" && "h-[52px] min-h-[52px]",
          externalTrailingClassName,
        ].filter(Boolean).join(" ")}>{externalTrailing}</div> : null}
      </div>
      {error ? <p className="m-0 text-xs leading-[1.5] text-[var(--danger-surface-foreground)]" id={errorId}>{error}</p> : hint ? <p className="m-0 text-xs leading-[1.5] text-[var(--text-secondary)]" id={hintId}>{hint}</p> : null}
    </div>
  );
});
